import pandas as pd
import numpy as np
from statsmodels.tsa.filters.hp_filter import hpfilter

def get_value(x):
    if isinstance(x, str):
        x = ''.join(c for c in x if c.isdigit() or c == '.')
    try:
        return float(x)
    except:
        return np.nan

def extract_erp_data(file_path, sheet_name):
    df = pd.read_excel(file_path, sheet_name=sheet_name)
    annual_data = {}
    for i in range(len(df)):
        year_str = str(df.iloc[i, 0])
        if year_str.strip().endswith('.') and year_str.strip()[:-1].isdigit():
            year = int(year_str.strip()[:-1])
            if 1973 <= year <= 2023:
                val = get_value(df.iloc[i, 1])
                annual_data[year] = val

    q2024 = []
    for i in range(len(df)):
        year_str = str(df.iloc[i, 0])
        if '2024: I' in year_str:
            q2024.append(get_value(df.iloc[i, 1]))
            for j in range(1, 4):
                if i + j < len(df):
                    next_val = get_value(df.iloc[i+j, 1])
                    if not np.isnan(next_val):
                        q_label = str(df.iloc[i+j, 0])
                        if any(q in q_label for q in ['II', 'III', 'IV']):
                            q2024.append(next_val)
            break
    if q2024:
        annual_data[2024] = np.mean(q2024)
    return annual_data

pce_nominal = extract_erp_data('ERP-2025-table10.xls', 'B10')
pfi_nominal = extract_erp_data('ERP-2025-table12.xls', 'B12')
cpi_df = pd.read_excel('CPI.xlsx')
cpi_data = dict(zip(cpi_df['Year'], cpi_df['CPI_2024']))

years = sorted(list(set(pce_nominal.keys()) & set(pfi_nominal.keys()) & set(cpi_data.keys())))
years = [y for y in years if 1973 <= y <= 2024]

data = []
for y in years:
    real_pce = pce_nominal[y] / cpi_data[y]
    real_pfi = pfi_nominal[y] / cpi_data[y]
    data.append({'RealPCE': real_pce, 'RealPFI': real_pfi})

df = pd.DataFrame(data)
pce_cycle, _ = hpfilter(np.log(df['RealPCE']), lamb=100)
pfi_cycle, _ = hpfilter(np.log(df['RealPFI']), lamb=100)
correlation = np.corrcoef(pce_cycle, pfi_cycle)[0, 1]

with open('answer.txt', 'w') as f:
    f.write(f"{correlation:.5f}\n")

